export enum CardRarity {
  BRONZE = 'BRONZE',
  SILVER = 'SILVER',
  GOLD = 'GOLD',
  ROTM = 'ROTM',
  ICON = 'ICON',
  ROTY = 'ROTY',
  ROTY_ICON = 'ROTY ICON',
  FIGHTERS = 'FIGHTERS',
  WATN = 'WATN',
  HERO = 'HERO'
}

export interface CardStats {
  ovr: number;
  lyricism: number;
  flow: number;
  sing: number;
  live: number;
  diss: number;
  charisma: number;
}

export interface SuperPower {
  id: string;
  name: string;
  iconUrl: string;
}

export interface RapperCardData {
  name: string;
  rarity: CardRarity;
  stats: CardStats;
  image: string | null; // Base64 or URL
  imagePosition: { x: number; y: number; scale: number };
  superpowers: SuperPower[];
}

export type AspectRatio = "1:1" | "3:4" | "4:3" | "9:16" | "16:9" | "2:3" | "3:2" | "21:9";
export type ImageSize = "1K" | "2K" | "4K";

export const AVAILABLE_SUPERPOWERS: SuperPower[] = [
  { id: 'rhymes', name: 'Rhymes Crafter', iconUrl: 'https://i.imghippo.com/files/vNrv7527Vlk.png' },
  { id: 'showmaker', name: 'ShowMaker', iconUrl: 'https://i.imghippo.com/files/RQb3623EB.png' },
  { id: 'artist', name: 'The Artist', iconUrl: 'https://i.imghippo.com/files/um8756xU.png' },
  { id: 'words', name: 'Words Bender', iconUrl: 'https://i.imghippo.com/files/phdJ6111L.png' },
  { id: 'story', name: 'Storyteller', iconUrl: 'https://i.imghippo.com/files/iCc6391Tg.png' },
  { id: 'battler', name: 'Battler', iconUrl: 'https://i.imghippo.com/files/KET1640s.png' },
  { id: 'career', name: 'Career Killer', iconUrl: 'https://i.imghippo.com/files/tev2511DrE.png' },
  { id: 'chopper', name: 'Chopper', iconUrl: 'https://i.imghippo.com/files/Fg5274pck.png' },
  { id: 'flow', name: 'Flow Switcher', iconUrl: 'https://i.imghippo.com/files/dHI7636jUs.png' },
  { id: 'freestyle', name: 'Freestyler', iconUrl: 'https://i.imghippo.com/files/Fkz1064WCk.png' },
  { id: 'notes', name: 'Notes Master', iconUrl: 'https://i.imghippo.com/files/em5378FZE.png' },
  { id: 'punchline', name: 'Punchline Machine', iconUrl: 'https://i.imghippo.com/files/EFHO4474cYk.png' },
];

import React, { useEffect, useRef, forwardRef, useImperativeHandle } from 'react';
import { CardRarity, RapperCardData } from '../types';

interface CardCanvasProps {
  data: RapperCardData;
  width?: number;
  height?: number;
}

export interface CardCanvasHandle {
  download: () => void;
}

// Map rarities to the provided image URLs
const RARITY_IMAGES: Record<CardRarity, string> = {
  [CardRarity.GOLD]: 'https://i.imghippo.com/files/tUt8745JBc.png',
  [CardRarity.SILVER]: 'https://i.imghippo.com/files/zC9861peQ.png',
  [CardRarity.BRONZE]: 'https://i.imghippo.com/files/TmM6820WtQ.png',
  [CardRarity.ROTM]: 'https://i.imghippo.com/files/UGRy5126YM.png',
  [CardRarity.ICON]: 'https://i.imghippo.com/files/jdCC2070F.png',
  [CardRarity.ROTY]: 'https://i.imghippo.com/files/PG9297qJ.png',
  [CardRarity.ROTY_ICON]: 'https://i.imghippo.com/files/iwZR6344ujs.png',
  [CardRarity.FIGHTERS]: 'https://res.cloudinary.com/dajbohgkl/image/upload/v1769857631/Gemini_Generated_Image_1thov51thov51tho_1_ppjydc.png',
  [CardRarity.WATN]: 'https://res.cloudinary.com/dajbohgkl/image/upload/v1769867674/Gemini_Generated_Image_ggfslsggfslsggfs_1_yyypqt.png',
  [CardRarity.HERO]: 'https://res.cloudinary.com/dajbohgkl/image/upload/v1770318066/Gemini_Generated_Image_ni624cni624cni62_1_xpx30q.png'
};

const LARGE_ICON_IDS = ['showmaker', 'artist', 'story', 'career', 'chopper'];
const EXPORT_SCALE = 3; // 3x Resolution for high quality

const CardCanvas = forwardRef<CardCanvasHandle, CardCanvasProps>(({ data, width = 400, height = 600 }, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  /**
   * Helper to load an image safely.
   */
  const loadImage = (src: string): Promise<HTMLImageElement | null> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => {
        console.warn(`Failed to load image: ${src}`);
        resolve(null);
      };
      img.src = src;
    });
  };

  /**
   * Helper to create the outer Card shape path.
   */
  const createCardPath = (ctx: CanvasRenderingContext2D, w: number, h: number) => {
    ctx.beginPath();
    const radius = 24;

    // Top Left Corner
    ctx.moveTo(radius, 0);
    ctx.lineTo(w - radius, 0);
    // Top Right Corner
    ctx.quadraticCurveTo(w, 0, w, radius);

    // Right Side to Bottom Point
    ctx.lineTo(w, h * 0.75); 
    // Shield Curve to tip
    ctx.bezierCurveTo(w, h * 0.9, w * 0.5, h * 0.96, w * 0.5, h); 
    ctx.bezierCurveTo(w * 0.5, h * 0.96, 0, h * 0.9, 0, h * 0.75); 

    // Left Side to Top
    ctx.lineTo(0, radius);
    // Top Left Corner
    ctx.quadraticCurveTo(0, 0, radius, 0);

    ctx.closePath();
  };

  const drawCard = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // --- High DPI Setup ---
    // Reset transform to identity to prevent accumulation
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    // Scale context for high resolution
    ctx.scale(EXPORT_SCALE, EXPORT_SCALE);

    // Clear (using logical dimensions)
    ctx.clearRect(0, 0, width, height);

    // --- Determine Colors based on Rarity ---
    // Default Colors (Gold base)
    let textColorName = '#0a0a0a';       // Black
    let textColorStatsLabel = '#5c4d3c'; // Brown/Gold
    let textColorStatsValue = '#0a0a0a'; // Black
    let textColorOvr = '#F5E6C8';        // Beige/Light Gold

    switch (data.rarity) {
      case CardRarity.BRONZE:
        // Bronze: Name and stats same as OVR
        textColorName = textColorOvr;
        textColorStatsLabel = textColorOvr;
        textColorStatsValue = textColorOvr;
        break;
      case CardRarity.SILVER:
        // Silver: OVR is white
        textColorOvr = '#FFFFFF';
        break;
      case CardRarity.ROTM:
        // ROTM: All text bright cyan
        const cyan = '#00FFFF';
        textColorName = cyan;
        textColorStatsLabel = cyan;
        textColorStatsValue = cyan;
        textColorOvr = cyan;
        break;
      case CardRarity.ICON:
        // Icon: OVR is black
        textColorOvr = '#000000';
        break;
      case CardRarity.ROTY:
         // ROTY: Pure white text
         textColorName = '#FFFFFF';
         textColorStatsLabel = '#FFFFFF';
         textColorStatsValue = '#FFFFFF';
         textColorOvr = '#FFFFFF';
         break;
      case CardRarity.ROTY_ICON:
         // ROTY ICON: All Black text
         textColorName = '#000000';
         textColorStatsLabel = '#000000';
         textColorStatsValue = '#000000';
         textColorOvr = '#000000';
         break;
      case CardRarity.FIGHTERS:
         // FIGHTERS: Light Gold text
         const fightersGold = '#F5E6C8';
         textColorName = fightersGold;
         textColorStatsLabel = fightersGold;
         textColorStatsValue = fightersGold;
         textColorOvr = fightersGold;
         break;
      case CardRarity.WATN:
         // WATN: Gold text
         const watnGold = '#FFD700';
         textColorName = watnGold;
         textColorStatsLabel = watnGold;
         textColorStatsValue = watnGold;
         textColorOvr = watnGold;
         break;
      case CardRarity.HERO:
         // HERO: Gold text
         const heroGold = '#FFD700';
         textColorName = heroGold;
         textColorStatsLabel = heroGold;
         textColorStatsValue = heroGold;
         textColorOvr = heroGold;
         break;
      default:
        // Keeps defaults defined above
        break;
    }

    // --- 1. Load Background Template ---
    const bgUrl = RARITY_IMAGES[data.rarity] || RARITY_IMAGES[CardRarity.GOLD];
    const bgImg = await loadImage(bgUrl);

    // --- 2. Clipping & Composition ---
    ctx.save(); // Save 1: Outer Card Clip

    createCardPath(ctx, width, height);
    ctx.clip(); // Restrict all drawing to card shape

    // Draw the template background first
    if (bgImg) {
       ctx.drawImage(bgImg, 0, 0, width, height);
    } else {
       ctx.fillStyle = '#222';
       ctx.fillRect(0, 0, width, height);
    }

    // --- 3. Rapper Image ---
    if (data.image) {
      const img = await loadImage(data.image);

      if (img) {
        const { x, y, scale } = data.imagePosition;
        const imgW = img.naturalWidth * scale;
        const imgH = img.naturalHeight * scale;
        const centerX = width / 2 + x;
        const centerY = (height * 0.45) + y; 

        ctx.save(); // Save 2: Rapper Clip

        // Define the "Window" where the rapper is visible.
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(width, 0);

        // Define the bottom edge of the rapper visibility (Top edge of the plate)
        const plateSideY = height * 0.62; 
        const plateCenterY = height * 0.65; 

        ctx.lineTo(width, plateSideY);
        // Curve down to center
        ctx.quadraticCurveTo(width / 2, plateCenterY, 0, plateSideY);

        ctx.lineTo(0, 0);
        ctx.closePath();
        ctx.clip();

        // Draw rapper
        ctx.drawImage(img, centerX - imgW / 2, centerY - imgH / 2, imgW, imgH);

        ctx.restore(); // Restore 2
      }
    }

    // --- 4. Superpowers ---
    if (data.superpowers && data.superpowers.length > 0) {
        const iconSize = 55; 
        const xCenter = 40; // Left margin center
        const gap = 8;

        // Calculate vertical centering
        // The available vertical space on the left is roughly from Y=180 to Y=420.
        // Moved down from 280 to 320 to match request
        const containerCenterY = 320;

        // Total height of the stack
        const totalHeight = (data.superpowers.length * iconSize) + ((data.superpowers.length - 1) * gap);

        // Starting Y position to ensure the stack is centered
        let currentY = containerCenterY - (totalHeight / 2);

        for (let i = 0; i < data.superpowers.length; i++) {
            const sp = data.superpowers[i];
            const img = await loadImage(sp.iconUrl);

            if (img) {
                // Aspect Ratio Logic to prevent squishing
                // Fit image within iconSize x iconSize box
                let scale = Math.min(iconSize / img.naturalWidth, iconSize / img.naturalHeight);

                // If it's NOT one of the "naturally big" icons, boost its scale
                if (!LARGE_ICON_IDS.includes(sp.id)) {
                    scale *= 1.25; 
                }

                const w = img.naturalWidth * scale;
                const h = img.naturalHeight * scale;

                // Calculate position to center the image within its specific slot
                // We use iconSize for the slot reference, but draw the image based on its calculated w/h
                // This allows the boosted images to slightly overflow the visual 55px box if needed, 
                // but since they were visually small, they should now look "normal" size.
                const xPos = xCenter - (w / 2);
                const yPos = currentY + (iconSize - h) / 2;

                ctx.save();
                // Draw Icon
                ctx.drawImage(img, xPos, yPos, w, h);
                ctx.restore();

                // Move to next slot
                currentY += iconSize + gap;
            }
        }
    }

    // --- 5. Text & Stats ---

    // NAME
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic'; 
    // Changed to 400 (Regular) weight and moved position down
    // Reduced from 44px by 12.5% -> 38.5px
    ctx.font = '400 38.5px Oswald'; 

    // Position name - Moved DOWN to approx 435px (0.725)
    const nameY = height * 0.725; 

    // Reset shadow defaults first
    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;

    // Add shadow/glow for specific rarities
    if (data.rarity === CardRarity.ROTY) {
        ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
        ctx.shadowBlur = 4;
        ctx.shadowOffsetX = 2;
        ctx.shadowOffsetY = 2;
    } else if (data.rarity === CardRarity.ROTY_ICON) {
        // White Outer Glow for ROTY ICON
        ctx.shadowColor = '#FFFFFF';
        ctx.shadowBlur = 50; // Increased even more
        ctx.shadowOffsetX = 0;
        ctx.shadowOffsetY = 0;
    } else if (data.rarity === CardRarity.FIGHTERS) {
        // Dark shadow for Fighters
        ctx.shadowColor = 'rgba(0, 0, 0, 0.7)';
        ctx.shadowBlur = 4;
        ctx.shadowOffsetX = 2;
        ctx.shadowOffsetY = 2;
    } else if (data.rarity === CardRarity.WATN) {
        // Gold Glow for WATN
        ctx.shadowColor = 'rgba(255, 215, 0, 0.5)';
        ctx.shadowBlur = 10;
        ctx.shadowOffsetX = 0;
        ctx.shadowOffsetY = 0;
    } else if (data.rarity === CardRarity.HERO) {
        // Gold Glow for HERO
        ctx.shadowColor = 'rgba(255, 215, 0, 0.5)';
        ctx.shadowBlur = 10;
        ctx.shadowOffsetX = 0;
        ctx.shadowOffsetY = 0;
    }

    ctx.fillStyle = textColorName; 
    ctx.fillText(data.name.toUpperCase(), width / 2, nameY);

    // STATS
    const statLabels = [
        { key: 'lyricism', label: 'LYRC' },
        { key: 'flow', label: 'FLOW' },
        { key: 'sing', label: 'SING' },
        { key: 'live', label: 'LIVE' },
        { key: 'diss', label: 'DISS' },
        { key: 'charisma', label: 'CHAR' }
    ];

    // Vertical Positions - Moved UP slightly on request
    const labelsY = height * 0.77; 
    const valuesY = height * 0.81; 

    // Horizontal Spacing
    // Spread out significantly to "fill the blue box" area
    const center = width / 2;
    // Steps from center: 25, 75, 125
    const step1 = 25;
    const step2 = 75;
    const step3 = 125;

    const xPositions = [
        center - step3, // LYRC (75px)
        center - step2, // FLOW (125px)
        center - step1, // SING (175px)
        center + step1, // LIVE (225px)
        center + step2, // DISS (275px)
        center + step3  // CHAR (325px)
    ];

    statLabels.forEach((item, index) => {
        const x = xPositions[index];

        // Label
        const labelWeight = data.rarity === CardRarity.ROTY_ICON ? '700' : '500';
        ctx.font = `${labelWeight} 12px Oswald`; 
        ctx.fillStyle = textColorStatsLabel;
        ctx.textAlign = 'center';

        if (data.rarity === CardRarity.ROTY_ICON) {
            ctx.lineWidth = 3; // Increased to 3 to be clearly visible
            ctx.strokeStyle = '#FFFFFF';
            ctx.strokeText(item.label, x, labelsY);
        }

        ctx.fillText(item.label, x, labelsY);

        // Value
        const valWeight = data.rarity === CardRarity.ROTY_ICON ? '700' : '400';
        ctx.font = `${valWeight} 22px Oswald`; // Bold for ROTY_ICON, Regular for others
        const valStr = data.stats[item.key as keyof typeof data.stats].toString();
        ctx.fillStyle = textColorStatsValue;
        ctx.fillText(valStr, x, valuesY);
    });

    ctx.restore(); // Restore 1 (Outer Clip)

    // --- 6. OVR Rating (Top Left) ---
    // Moved DOWN more and RIGHT more, reduced size
    const ovrX = 88; 
    const ovrY = 172; 

    ctx.save();
    ctx.font = 'bold 60px Oswald'; // Reduced size slightly
    ctx.textAlign = 'center';

    ctx.fillStyle = textColorOvr;

    // Reset shadow
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;

    if (data.rarity === CardRarity.ROTY_ICON) {
        // White Outer Glow
        ctx.shadowColor = '#FFFFFF';
        ctx.shadowBlur = 50; // Increased even more
    } else if (data.rarity === CardRarity.ROTY) {
        // Standard ROTY Shadow
        ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
        ctx.shadowBlur = 4;
        ctx.shadowOffsetX = 2;
        ctx.shadowOffsetY = 2;
    } else if (data.rarity === CardRarity.ICON) {
        // No shadow for standard ICON
        ctx.shadowColor = "transparent";
        ctx.shadowBlur = 0;
    } else if (data.rarity === CardRarity.FIGHTERS) {
         // Dark shadow for Fighters
         ctx.shadowColor = 'rgba(0, 0, 0, 0.7)';
         ctx.shadowBlur = 4;
         ctx.shadowOffsetX = 2;
         ctx.shadowOffsetY = 2;
    } else if (data.rarity === CardRarity.WATN) {
         // Gold Glow for WATN
         ctx.shadowColor = 'rgba(255, 215, 0, 0.5)';
         ctx.shadowBlur = 10;
    } else if (data.rarity === CardRarity.HERO) {
         // Gold Glow for HERO
         ctx.shadowColor = 'rgba(255, 215, 0, 0.5)';
         ctx.shadowBlur = 10;
    } else {
        // Default Dark Shadow for Gold, Silver, Bronze, etc.
        ctx.shadowColor = "rgba(0,0,0,0.6)";
        ctx.shadowBlur = 6;
        ctx.shadowOffsetY = 2;
    }

    ctx.fillText(data.stats.ovr.toString(), ovrX, ovrY);

    ctx.restore();
  };

  useEffect(() => {
    drawCard();
  }, [data, width, height]);

  useImperativeHandle(ref, () => ({
    download: () => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const sanitize = (str: string) => str.trim().replace(/[\s\/\\:*?"<>|]+/g, '_');

      const namePart = sanitize(data.name) || 'Untitled';
      const rarityPart = data.rarity;
      const ovrPart = data.stats.ovr;
      const powersPart = data.superpowers.map(sp => sanitize(sp.name)).join('_');

      let filename = `${namePart}_${rarityPart}_${ovrPart}`;
      if (powersPart) {
        filename += `_${powersPart}`;
      }
      filename += '.webp';

      const link = document.createElement('a');
      link.download = filename;
      link.href = canvas.toDataURL('image/webp');
      link.click();
    }
  }));

  return (
    <div className="relative shadow-2xl rounded-[30px] overflow-hidden" style={{ width, height }}>
      <canvas 
        ref={canvasRef} 
        width={width * EXPORT_SCALE} 
        height={height * EXPORT_SCALE}
        style={{ width, height }} 
        className="bg-transparent"
      />
    </div>
  );
});

CardCanvas.displayName = 'CardCanvas';

export default CardCanvas;
